begin transaction isolation level repeatable read read only; set local statement_timeout='15s'; set local lock_timeout='2s'; select jsonb_build_object('source_project_ref','pfvblcopcmairdfeqdep','observed_at_utc',clock_timestamp(),'visibility_precedence',(select row_to_json(r) from (select count(*) filter(where a.steam_visibility_checked_at > u.steam_visibility_checked_at) as account_newer,count(*) filter(where u.steam_visibility_checked_at > a.steam_visibility_checked_at) as profile_newer,count(*) filter(where a.steam_visibility_checked_at is not null and u.steam_visibility_checked_at is null) as only_account_dated,count(*) filter(where u.steam_visibility_checked_at is not null and a.steam_visibility_checked_at is null) as only_profile_dated,count(*) filter(where a.steam_visibility_checked_at is not distinct from u.steam_visibility_checked_at and (a.steam_library_visible is distinct from u.steam_library_visible or a.steam_playtime_visible is distinct from u.steam_playtime_visible or a.steam_last_played_visible is distinct from u.steam_last_played_visible)) as equal_time_value_conflicts from public.app_accounts a join public.app_users u on u.id=a.id) r)) as audit; commit;
